// R5/B-1: normaliza la salida del Agente Aclaración y arma el sobre para enviar.
// VALIDACION DEFENSIVA (riesgo residual #1 de Fable): el output parser no garantiza
// el schema. Si falta una clave, el tipo no cierra, o escalar=false con pregunta
// vacia -> se fuerza escalada. El prompt no alcanza; el guard manda.
const d = $('Prompt Aclaración').first().json;
let out = {};
try {
  const raw = $input.first().json;
  out = raw.output || raw.data || raw;
  if (typeof out === 'string') out = JSON.parse(out);
} catch (e) { out = {}; }

const pregunta = String(out.pregunta || '').trim();
// escalar si: el agente lo pidio, no hay pregunta usable, o el output vino ilegible
const escala = out.escalar === true || pregunta === '' || typeof out.escalar !== 'boolean';
const final = escala ? '' : pregunta;

return [{ json: {
  ...d,
  final,
  accion: 'repregunto',        // ya existe en el enum bot.accion (base 2026-08-05)
  hayRespuesta: final.length > 0,
  productoResuelto: null,       // una repregunta no resuelve producto
  notas: 'v10-aclaracion ' + (escala ? 'fuente=escala' : 'fuente=agente')
    + (out.motivo ? ' motivo=' + String(out.motivo).slice(0, 120) : ''),
} }];
